using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;
using ruru_api.model;

namespace ruru_api.data.Seed;

/// <summary>One row of exercises.json.</summary>
public record ExerciseSeedRow(
    string Name,
    ExerciseType Type,
    string BodyPart,
    string Equipment,
    EquipmentGroup EquipmentGroup,
    ExperienceLevel Level);

/// <summary>
/// The starter exercise catalogue, embedded in the assembly from src/data/Seed/exercises.json.
/// The file is generated by backend/tools/select_exercises.py; edit the script, not the file.
/// </summary>
public static class ExerciseSeedData
{
    private const string ResourceName = "exercises.json";

    private static readonly JsonSerializerOptions Options = new()
    {
        PropertyNameCaseInsensitive = true,
        Converters = { new JsonStringEnumConverter() },
    };

    public static IReadOnlyList<ExerciseSeedRow> Load()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource '{ResourceName}' is missing.");

        return JsonSerializer.Deserialize<List<ExerciseSeedRow>>(stream, Options) ?? [];
    }
}
